import * as T from './three.module.js';
export function neighbourHen(root,slot=0){const legs=[],fur=new T.MeshStandardMaterial({color:slot%2?'#dfc791':'#b99051',roughness:.96}),red=new T.MeshStandardMaterial({color:'#ab4b38',roughness:.9}),gold=new T.MeshStandardMaterial({color:'#b79450'}),dark=new T.MeshStandardMaterial({color:'#383b32'});function oval(x,y,z,a,b,c,mat=fur,parent=root){const m=new T.Mesh(new T.SphereGeometry(1,12,8),mat);m.position.set(x,y,z);m.scale.set(a,b,c);parent.add(m);return m;}oval(0,1,0,.58,.68,.83);oval(0,1.58,.55,.26,.39,.25);oval(0,1.94,.65,.31,.32,.33);const beak=new T.Mesh(new T.ConeGeometry(.13,.37,6),gold);beak.rotation.x=Math.PI/2;beak.position.set(0,1.93,1.0);root.add(beak);for(let k=0;k<3;k++)oval(0,2.25+k*.01,.50+k*.14,.085,.14,.10,red);oval(0,1.68,.90,.08,.14,.08,red);for(const side of [-1,1]){oval(side*.265,2.01,.80,.035,.045,.03,dark);oval(side*.48,1.08,-.07,.17,.44,.60);const leg=new T.Group();leg.position.set(side*.23,.55,0);root.add(leg);const lower=new T.Mesh(new T.CylinderGeometry(.045,.055,.5,7),gold);lower.position.y=-.23;leg.add(lower);for(let j=0;j<3;j++){const toe=new T.Mesh(new T.BoxGeometry(.04,.04,.27),gold);toe.position.set((j-1)*.07,-.48,.08);toe.rotation.y=(j-1)*.35;leg.add(toe);}legs.push(leg);}for(let i=0;i<4;i++){const f=oval((i-1.5)*.13,1.48,-.75,.08,.46,.21,i%2?dark:fur);f.rotation.x=-.6;}root.scale.setScalar(.45);return legs;}
